task.vi:
Giả sử bạn nạp chồng toán tử << như sau:

ostream& operator<<(ostream& stream, const Rational& rational)
{
  stream << rational.getNumerator() << " / "
    << rational.getDenominator();
  return stream;
}

Bạn có còn cần phải định nghĩa `friend ostream& operator<<(ostream& stream, Rational& rational);` bên trong lớp Rational nữa không? Giải thích rõ lý do.

task.en:
Suppose you overload the << operator as follows:

ostream& operator<<(ostream& stream, const Rational& rational)
{
  stream << rational.getNumerator() << " / "
    << rational.getDenominator();
  return stream;
}

Do you still need to define `friend ostream& operator<<(ostream& stream, Rational& rational);` in the Rational class? Explain why.

example.code:
#include <iostream>

class Rational {
private:
    int numerator;
    int denominator;
public:
    Rational(int num = 0, int den = 1) : numerator(num), denominator(den) {}

    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }

    // Overloaded as nonmember friend functions
    friend std::ostream& operator<<(std::ostream& out, const Rational& r) {
        out << r.numerator << "/" << r.denominator;
        return out;
    }

    friend std::istream& operator>>(std::istream& in, Rational& r) {
        int n,d;if(in >> n >> d){if(d==0)in.setstate(std::ios::failbit);else {r.numerator=n;r.denominator=d;}}
        return in;
    }
};

int main() {
    Rational r1;
    std::cin >> r1;
    Rational r2(3, 4);
    std::cout << r1 << " followed by " << r2 << std::endl;
    return 0;
}

#include <iostream>

class Rational {
private:
    int numerator;
    int denominator;
public:
    // Single-argument constructor allows implicit conversion from int
    Rational(int num = 0, int den = 1) : numerator(num), denominator(den) {}

    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }

    friend std::ostream& operator<<(std::ostream& out, const Rational& r) {
        out << r.numerator << "/" << r.denominator;
        return out;
    }
};

// Nonmember symmetric operator+
Rational operator+(const Rational& r1, const Rational& r2) {
    int num = r1.getNumerator() * r2.getDenominator() + r2.getNumerator() * r1.getDenominator();
    int den = r1.getDenominator() * r2.getDenominator();
    return Rational(num, den);
}

int main() {
    Rational r1(2, 3);

    // r1 + 4 converts 4 to Rational(4, 1)
    Rational res1 = r1 + 4;
    // 4 + r1 also converts 4 to Rational(4, 1) thanks to nonmember operator+
    Rational res2 = 4 + r1;

    std::cout << "r1 + 4 is " << res1 << std::endl;
    std::cout << "4 + r1 is " << res2 << std::endl;
    return 0;
}
